  "10gamlj": "رتی گین٘بیٹ",
  "12sipei": "پہلے دس چالاں کھیڈ نوں آکار دن٘دیءآں ہن۔ (1) کبزا کرن جاں کین٘در نوں نین٘ترت کردیءآں ہن (e4, d4, e5, d5) موہراں اتے ٹکڈءآں دے نال۔ (2) پہلاں چھوٹے ٹکڈے وکست کردے ہنہ آم تور اتّے نائیٹس, پھر بشپ, پہلی وار اکّ چن٘گے ورگ لئی, (3) کیسل, آم تور اتّے 10 توں شرو ہوݨ توں پہلاں۔ (4) بناں کسے کارن دے دو وار اکّ ٹکڈے نوں نہیں ہلاؤن٘دے (چڈن, پھسݨ توں پرہیز کرو)۔ (2) راݨی نوں بہت جلدی باہر نا کڈھّݨا, پھر انھاں نوں کھلّہے جاں ادھّے-کھلّہے پھائیلاں نال جوڈنا نا کرو۔",
  "sbo3hu": "شروءآتی راݨی اگّے ودھدی ہیہ انھاں توں بچݨا کؤں",
  "1jqk210": "راݨی تہاڈا سبھ توں کیمتی ٹکڈا ہے, اس لئی جدوں اہ جلدی ساہمݨے آؤن٘دا ہے تاں ورودھی چھوٹے ٹکڈے وکست کردا ہے اتے اس دا پچھّا کردا ہے, اتے ہریک پچھّا اکّ ستن٘تر وکاسشیل کدم ہے (اکّ گمّ ہوئی ٹین٘پو)۔ اداہرݨ وجوں, 1.e4 e5 2.Qh5 Nc6 3.Bc4 بلیک نوں ساتھی نوں روکݨا چاہیدا ہے f7 اس نال 3...g6 (جاں 3...Qe7), نہیں 3...Nf6?? اس کارن 4.Qxf7#اس توں باءاد. 3...g6 4.Qf3 Nf6 چٹّی راݨی نوں پھر توں اگّے ودھݨا پین٘دا ہے۔ سرپھ اکّ ٹھوس کارن کرکے راݨی نوں جلدی باہر کڈھّݨا پین٘دا ہیہ اکّ کیپچر جو اݨورتے ہو جان٘دا ہے, جاں اکّ سپشٹ رݨنیتی۔",
  "sd8q9": "جدوں اتے کس ترھاں دا راہ ہے",
  "1v3wara": "کاسٹلن٘گ راجے نوں اکّ سرکھّءات کونے وچّ رکھّدی ہے اتے کین٘در ولّ اکّ روک لءآؤن٘دا ہے۔ کن٘گسائیڈ کاسٹلن٘گ (O-O) آم تور اتّے تیز ہن٘دا ہیہ تہانوں سرپھ جی-کنائیٹ اتے ایپھّ-بشپ نوں لجاݨ دی زرورت ہن٘دی ہے۔ کئینسائیڈ کاسٹلن٘گ (O-O-O) سدھّے ڈی-پھائیل اتّے روک رکھّدا ہے, پر راجے c1 کی تھوڈا جہا سن٘پرک ہے اتے اس نوں زرورت ہے? a2- پھون ڈھکّءآ ہوئا جاں اکّ راجا ولّ جان٘دا ہے b1جدوں دوویں پاسے الٹ کھن٘بھاں اتّے ہن٘دے ہن, تاں کھیڈ دشمݨ دے راجے ولّ اکّ موہرے دی دوڈ بݨ جان٘دی ہے۔ کین٘در دے کھلّہݨ توں باءاد آپݨے راجے نوں وچکار نا چھڈّ دؤہ ادوں ہی تسیں ساتھی کرن لئی سبھ توں آسان ہن٘دے ہو۔",
  "1hidsw7": "کھلّہݨ وچّ کمزور f7 (f2) ورگ",
  "1m6menm": "کھیڈ دے شرو وچّ, بلیک f7 ورگ (وھائیٹ f2) سرپھ راجے دءآرا بچاءا کیتا جان٘دا ہے, اس لئی اہ اکّ بشپ لئی اکّ نشانا ہے۔ c4 g5 اتے راݨی۔ سبھ توں تیز جال (شولر دا میٹ, پھریڈ لائیورہ 1.e4 e5 2.Nf3 Nc6 3.Bc4 Nf6 4.Ng5 d5 5.exd5 Nxd5? 6.Nxf7) سبھ دا ادیش ہے f7. بچاءا کرناہ کھیڈݨا...Nf6 سمیں دے نال, کلھے جلدی اتے ٹو نائیٹس وچّ بلیک دے روپ وچّ, جواب 5.exd5 اس نال 5...Na5 نائیٹ نال مڈ کبزا کرن دی بجائے۔",
  "1adsmpj": "اوپنن٘گ ٹریپ, شروءآت کرن والے اکسر ملدے ہن",
  "h6d4vp": "ودوان دا میٹہ 1.e4 e5 2.Bc4 Nc6 3.Qh5 Nf6?? 4.Qxf7#; 3...g6 جاں 3...Qe7 نال بچاءا کرو۔ پھول دا میٹہ 1.f3 e5 2.g4?? Qh4#; آپݨے راجے لئی وکرݨ نہیں کھولھو۔ لگل دا ٹریپہ 1.e4 e5 2.Nf3 d6 3.Bc4 Bg4 4.Nc3 g6? 5.Nxe5! Bxd1?? 6.Bxf7+ Ke7 7.Nd5#۔ آم سبکہ اکّ پنّ ہمیشا اکّ ٹکڈا نہیں رکھّدا, اتے جدوں وی کوئی ورودھی \"جافی\" تہانوں امل وچّ پاؤن٘دا ہے, پچھّدا ہے ک کؤں۔",
  "1be41z": "گان٘بیٹسہ گتی لئی اکّ موہرا دیݨا",
  "4x5i5m": "تیزی نال وکاس, کھلّہیءآں پھائیلاں جاں راجے اتّے ہملا کرن دے بدلے وچّ اکّ گین٘بل (کئی وار ہور) کھلّہدا ہے۔ بلیدان بݨاؤݨ والے پکھّ نوں سرگرمی نال کھیڈݨا چاہیدا ہے; جے ورودھی نوں وکست کرنا پین٘دا ہے اتے کلھے بݨاؤݨا پین٘دا ہے, تاں اہ سبھ اکّ گمّ ہوئا موہر ہے۔ سویکار کرن والا پکھّ وکاس اتے راجا سرکھّءآ لئی سہی پل نوں واپس کرنا چاہیدا ہے نا ک ہر کیمت اتّیہ کئینز گین٘بیٹ (جے بلیک اگّے ودھدا ہے)۔ c4, وھائیٹ آم تور اتّے موہرے نوں آسانی نال مڈ پراپت کردا ہے), کن٘گ دے گین٘بیٹ, اوانس گین٘بیٹ, ڈینّمارکی گین٘بیٹ۔",
