  "1hha0i7": "جدوں ورودھی پھڈدا ہے اتے تہانوں مڈ کبزا کرن دی امید کردا ہے, تاں پہلاں کھیڈݨ لئی کئی وار اکّ مزبوت کدم ہن٘دا ہیہ اکّ چیکّ, اکّ وڈّا خترا, جاں اکّ ہور کیپچر۔ اکّ ان-ٹو-بدلی کدم \"ٹیک این٘ڈ ریٹیک\" گݨنا نوں پریشان کردا ہے۔ رپھلیکس دءآرا مڈ کبزا کرن توں پہلاں, پہلاں جان٘چ اتے دھمکیءآں نوں دیکھو۔",
