  "cmvxf3": "جدوں سمگّری وچّ اگّے کہاہ اکّ اسانی نال جتّ پراپت ان٘تم گیم تکّ پہن٘چݨ لئی آدان-پردان ٹکڈے (پون نہیں)۔ جدوں پچھّیہ آدان-پردان توں پرہیز کرو, موہرے رکھّو اتے کاؤن٘ٹرپلے دی بھال کرو۔ جدوں کھچاءا ہوئاہ آپݨے آپ نوں آزاد کرن لئی کجھ ٹکڈے بدلو۔ ورودھی دے ہملاور ٹکڈءآں نوں ایکسچین٘ج کرو اتے آپݨے سرگرم کمّاں نوں رکھّو۔ ورودھی دے چن٘گے بشپ لئی آپݨے برے بشپ دا پتا لگاؤݨا اکّ پھائدا ہے۔",
  "ht9l4o": "پروپھائیلیکسسہ ورودھی کی چاہن٘دے ہن?",
