  "1qopdgf": "موہرے دا کین٘در اتے اس نوں کمزور کرنا",
  "xbbabg": "اکّ موہرے دا کین٘در (کمّ 'تے) e4 اتے d4) جگہا دن٘دا ہے اتے دشمݨ دے ٹکڈءآں نوں سیمت کردا ہے۔ ہائیپرموڈرن کھیڈ ورودھی نوں اکّ کین٘در بݨاؤݨ اتے پھر اس اتّے ٹکڈءآں اتے موہراں نال ہملا کردی ہے (...c5, ...e5, ...f6) اکّ بن٘د کین٘در (پان بن٘د) دے نال, کھیڈ کھن٘بھاں اتّے ہملے کرن لئی جان٘دی ہے; اکّ کھلّہا کین٘در, تیز وکاس اتے راجا سرکھّءآ مہتّوپورن دے نال۔",
  "rdaiwm": "اوپوسائیٹ-سائیڈ کاسٹلن٘گہ دشمݨ راجے ولّ موہراں اتّے ہملا کرو تاں جو روکس لئی پھائیلاں کھولھ سکݨ; تیز پکھّ آم تور اتّے جتّدا ہے۔ سام-سائیڈ کاسٹلن٘گہ آپݨے راجے دے ساہمݨے موہراں نوں دھکّݨ دی بجائے ٹکڈءآں نال ہملا (کئینی, نائیٹ اتے بشپ نوں راجا ولّ چھڈّ کے)۔ اینیمی راجا اجے وی وچکارہ کین٘در نوں موہراں نال کھولھو, اتھّوں تکّ ک اکّ بلیدان دی کیمت 'تے وی۔ تہانوں راجے دے نیڈے ڈپھین٘ڈراں نالوں ودھیرے ہملاوراں دی زرورت ہے۔",
  "lt1w6h": "اخیرلی کھیڈ وچ بادشاہ وی لڑدا اے",
  "oqezje": "اکّ وار جدوں راݨیءآں بن٘د ہو جان٘دیءآں ہن اتے کجھ ٹکڈے رہن٘دے ہن, تاں راجے نوں ہݨ ساتھی نہیں ڈرداہ اس نوں اکّ وار کین٘در وچّ لءآئا جان٘دا ہے, اتے آپݨے موہراں دی رکھّءآ کرن اتے دشمݨ دے لوکاں نوں پھڈن لئی اس دی ورتوں کرو۔ موہرے ان٘ت دیءآں کھیڈاں وچّ, ودھیرے سرگرم راجا اکسر نتیجا نردھارت کردا ہے۔",
  "1fc6m76": "ورودھی دھر اتے پرمکھّ ورگ (کن٘گ این٘ڈ ہار بنام راجا)",
  "156bncz": "ورودھی دھرہ دو راجءآں نوں اکّ دوجے نوں اکّ ورگ توں وکھّ کرنا; پکھّ \"ورودھی دھر نوں اگّے نہیں ودھاؤݨا\" اتے دوجے راجے نوں واپس دھکّ سکدا ہے۔ بی توں جی پھائیلاں اتّے اکّ موہرے دے نال, مزبوت ٹیم جتّدی ہے جے اس دا راجا اکّ پرمکھّ ورگ تکّ پہن٘چدا ہے۔ مدھّ (اداہرݨ وجوں e4) وچّ اکّ موہرے وچّ مکھّ ورگ d6,e6,f6 ہے; پن٘جویں رین٘ک (e5) اتّے اکّ موہرے وچّ d7,e7,f7 وی ہن۔ پرن٘سپپہ راجا موہرے توں اگّے جان٘دا ہے; جلدی ہی موہرے نوں نا دھکّو۔ اکّ جاں ایچ-پان دے نال, جے ڈپھین٘ڈن٘گ راجا کونے تکّ پہن٘چدا ہے تاں اہ آم تور اتّے ڈراءا ہن٘دا ہے۔",
  "2oijvr": "اکّ ورگ دی تسویر جس دے پاسے اکّ پاس کیتے موہرے توں اس دے پرچار ورگ وچّ دوڈدے ہن۔ جے دشمݨ راجا اس ورگ دے ان٘در کدم رکھّ سکدا ہے (اہ کس دا کدم ہے), تاں اہ موہرے نوں پھڈدا ہے; جے نہیں, تاں موہرا اتشاہت کردا ہے۔ اس دے شروءآتی رین٘ک اتّے اکّ موہرے دی گݨتی جویں ک پہلاں ہی اگلے رین٘ک اتّے, کؤن٘ک اہ دو ورگ نوں اگّے ودھا سکدا ہے۔",
