  "16xqsgv": "روک اتے ستّویں رین٘ک بنام روک اتّے موہرے ہوئے, ترکّی ورگ اتّے مزبوت راجا اتے دشمݨ دے راجے نے اکّ پھائیل نال کٹّ دتّا۔ کویں جتّݨا ہیہ آپݨے روک نوں چوتھے رین٘ک وچّ لءآؤݨا (تہاڈے پکھّ توں بݨءآ), آپݨے راجے نوں ترکّی ورگ توں باہر جاݨ دؤ; جدوں دشمݨ پھائیل دے نال جان٘چ کردا ہے, تاں تہاڈا راجا تہاڈے روک ولّ تردا ہے, اتے پھر تہاڈے روک نے چیکّ نوں چوتھے رین٘ک اتّے روک دتّا۔ اہ روک این٘ڈگیم وچّ سبھ توں مہتّوپورن جتّ دی ستھتی ہے۔",
