  "1pfu08h": "روک اتے موہرے بنام روک, موہرے دے ساہمݨے ڈپھین٘ڈن٘گ کن٘گ نال۔ آپݨے روک نوں آپݨے پکھّ (بلیک لئی چھیواں درجا) توں تیجے رین٘ک اتّے رکھّو تاں جو دشمݨ راجا اگّے نہیں ودھ سکے۔ جدوں موہرے اس رین٘ک ولّ ودھدے ہن, تاں تہاڈا روک ترن٘ت ورودھی دے پچھلے رین٘ک وچّ جان٘دا ہے اتے پچھّے توں جان٘چ کردا ہے۔ اس سیٹّءاپّ ڈراءا نوں پھڈو۔",
