  "aifw7z": "چیز دی شروءآت 6ویں سدی دے آس پاس بھارت وچّ کھیڈ چٹورن٘گا توں ہوئی سی, جو پھارس (شران٘ج) تکّ پھیل گئی سی, پھر ارب سن٘سار وچّ یورپ وچّ پھیل گئی سی۔ 15ویں سدی دے اکھیر وچّ راݨی اتے بشپ نے آپݨے شکتیشالی آدھنک چالاں پراپت کیتیءآں سن, جس نال کھیڈ تیزی اتے تیز ہو گئی سی۔ پہلی ادھکارت وشو چین٘پیءانشپ 1886 وچّ ہوئی سی۔ 1990 دے دہاکے توں, کن٘پؤٹر (ڈیپ بلو نے کاسپاروو نوں ہرائا) اتے پھر ان٘جݨاں جویں ک Stockfish بدل کے لوک کویں سکھلائی لین٘دے ہن۔",
