  "xmcnin": "مکھائل بوٹونک نے 1938 (مارچو) دے اے. وی. آر. او. ٹورنامین٘ٹ وچّ سابکا وشو چین٘پیءان جوس رال کیپابلان٘کا نوں ہرائا۔ اکّ نمزو-ان٘ڈیءان توں, وھائیٹ نے e4-e5-f4-f5 نال اکّ کین٘در بݨائا, پھر 30.Ba3!! اکّ بشپ نوں کالی راݨی نوں دور کھچّݨ لئی بلیدان دتّا, اتے 31.Nh5+! ای-پان لئی جاݨ دا راہ ساف کیتا۔ اہ کین٘دری یوجنابن٘دی دا اکّ کلاسک ہے جس نوں اکّ چن٘گی سمیں دی رݨنیتی نال جوڈءآ گءآ ہے۔",
  "1tafz2t": "کھیڈ آف د سین٘چری (برنے-پھشر, 1956)",
  "1aggrgq": "بوبی پھشر, جو اس ویلے 13 سالا بلیک دی بھومکا نبھا رہا سی, نے 1956 وچّ نؤیارک وچّ ڈونالڈ بائرن نوں ہرائا سی۔ اہ کدم 17...Be6!!ای کن٘دھ چتّر راہیں چٹّے دے ٹکڈءآں دی اکّ لڈی دے بدلے وچّ راݨی نوں دن٘دا ہے, اتے پھر کالے دے چھوٹے ٹکڈے چٹّے راجے نوں ساتھی وچّ لجاݨ لئی جوڈدے ہن۔ کھیڈ اکّ سن٘پورن اداہرݨ ہے جو گݨتی سمگّری دی بجائے ٹکڈے دی گتیودھی دءآرا اکّ ستھتی نوں ان٘دازا لگاؤݨ دی بجائے۔",
  "1or2j4s": "پھشر-سپیسکی, گیم 6 (ریکجاوک 1972)",
  "6dma5h": "1972 وشو چین٘پیءانشپ میچ دا گیم 6۔ پھشر, جس نے لگبھگ سرپھ 1.e4 کھیڈءآ سی, نے 1.c4 نال سارءآں نوں ہیران کر دتّا اتے مہاراݨی دے گین٘بیٹ گھوشݨا پتّر دے ٹارٹاکوور بھنّتاواں وچّ اکّ سن٘پورن رݨنیتک کھیڈ کھیڈیہ e4-e5 نوں اگّے ودھائا, پھر ایپھّ-پھائیل اتّے روکس نوں پیلن٘گ کرو اتے بلیک دے کن٘گسائیڈ نوں توڈ دتّا۔ اہ کہا جان٘دا ہے ک سپاسکی کھد کھیڈ توں باءاد کھڈہا سی اتے پرشن٘سا کیتی گئی سی۔ پھشر نے میچ جتّءآ اتے اہ پہلا امریکی وشو چین٘پیءان بݨ گءآ۔",
