  "97g76a": "1997 دے ریمیچ دی پھیسلاکنّ کھیڈہ آئی. بی. ایمّ. دے ڈیپ بلو سپر کن٘پؤٹر نے نائیٹ بلیدان دا دھنّواد کردے ہوئے کیرو-کان ڈپھین٘س وچّ گیری کاسپاروو نوں 19 چالاں وچّ ہرائا۔ 8.Nxe6 منّءآ جان٘دا ہے ک کارسپاروو نے کدم دے کرم نوں ملا دتّا سی...h6ڈیپ بلو نے میچ 3.5-2.5 جتّءآ, پہلی وار اکّ کن٘پؤٹر نے سٹین٘ڈرڈ ٹائیم کن٘ٹرول وچّ اکّ میچ وچّ وشو چین٘پیءان نوں ہرائا۔",
  "bus3pl": "کاسپاروو-ٹوپالووہ \"کاسپروو دا انیتک\" (وجک اءآن زی 1999)",
  "12gfstt": "گیری کاسپاروو نے 1999 وچّ وک این زی وکھے ویسلن ٹوپالوو نوں روک بلیدان نال ہرائا سی۔ 24.Rxd4!!پورے بورڈ وچّ اکّ راجے دی بھال شرو کردے ہوئے, کالے راجا نوں راݨی دے کنارے توں وھائیٹ دے پہلے رین٘ک تکّ لجائا گءآ سی۔ بہت سارے لوک اس نوں کاسپاروو دی سبھ توں سن٘در کھیڈ منّدے ہن, جو اکّ ستھائی پہلکدمی لئی ڈون٘گھی گݨنا اتے بلیدان دیݨ والی سمگّری نوں درساؤن٘دے ہن۔",
  "3yoknn": "وشو چین٘پیءانشپ میچاں دا اتہاس",
  "dc01i3": "1886 وچّ پہلا ادھکارت میچہ سٹینٹز نے بؤنس آئرس وچّ زکرٹورٹ نوں ہرائاہ الیکھائین نے کیپابلان٘کا نوں ہرائا۔ 1948: ایپھّ. آئی. ڈی. ای. نے الیکھن دی موت توں باءاد اکّ چین٘پیءان دی چوݨ کرن لئی اکّ ٹورنامین٘ٹ آیوجت کیتا, اتے بوٹوننک نے کھتاب جتّءآ۔ 1972 وچّ رکجاوک وچّہ پھشر نے شیت یدھّ دوران سپاسکی نوں ہرائا۔ 1975: پھشر نے آپݨے ختاب دا بچاءا نہیں کیتا اتے کارپوو چین٘پیءان بݨ گءآ۔ 1984-85: کارپوو-کسپاروو میچ نوں 48 گیماں توں باءاد روک دتّا گءآ سی; 1985 دے ریمیچ کیسپاروو وچّ کیسپیروو نے جتّ پراپت کیتی۔ کھتاب ون٘ڈءآ گءآ سی (پی. سی. اے. اتے ایپھّ. آئی. ڈی. ای.), اتے 2006 وچّ دبارا ایکیکرت کیتا جدوں کریمنک نے ٹوپالوو نوں ہرائا سی۔ 2007: آنن٘د چین٘پیءان بݨ گءآ۔ 2013 چینئی وچّہ کارلسن نے آنن٘د نوں ہرائا اتے 2023 تکّ کھتاب جتّءآ۔ 2023: کارلسن نے نہیں کھیڈءآ, اتے ڈن٘گ لرین نے نیپومنیءآچچی نوں ہرائا۔ سن٘گاپر وچّ 2024 دے اکھیر وچّہ گکیش ڈومراجو (موت 18 سال) نے ڈن٘گ لبرن نوں ہرائا اتے سبھ توں گھٹّ امر دا وشو چین٘پیءان بݨ گءآ۔ (2025 تکّ) ہال ہی دے میچاں دے بہت سارے (کلاسیکل گیمز, پھر تیز ٹائی-بریک جے کوئی ہووے): 1972 دے پھشر نے سپاسکی نوں 12.5-8.5 ہرائا۔ 1985 دے کاسپاروو نے کارپوو نوں ہرائا (22 سال دی امر وچّ, لاسپاروو, گکیش تکّ سبھ توں گھٹّ امر دا چین٘پیءان سی)۔ 2013 کارلسن نے آنن٘د 6.5-3.5 نوں ہرائا۔ 2014 کارلسن نے آنن٘د 6.5-4.5 نوں ہرائا۔ 2016 کارلسن-کارجاکن نے 6-6 نال ڈراءا کیتا, اتے کارلسن نے ریپڈ ٹائی-بریک 3-1 نال جتّ پراپت کیتی۔ 2018 کارلسن-کارءآنا نے سارے 12 میچ ڈراءا کیتے, اتے کارلسن نے ٹائی-بریک 3-0 نال جتّ پراپت کیتی۔ 2021 کارلسن نے نیپولیءانچچی 7.5-3.5 نوں ہرائا۔ 2023 ڈن٘گ لرین-نیپومنیءآچچی نے 7-7 نال ڈراءا کیتا, اتے ڈن٘گ نے ریپڈ ٹائی-بریک 2.5-1.5 جتّءآ۔ 2024 گکیش نے ڈن٘گ لرین 7.5-6.5 نوں کوئی ٹائی-بریک دی زرورت نہیں سیہ گیم 14 (آکھری) وچّ, ڈن٘گ نے لگبھگ ڈراءا ہوئے روک این٘ڈگیم وچّ گلتی کیتی اتے گکیش نے جتّ پراپت کیتی۔",
