  "kf9dno": "1997 وچّ, آئی. بی. ایمّ. دے ڈیپ بلو سپر کن٘پؤٹر نے گیری کاسپاروو 3.5-2.5 نال ہرائا۔ ادوں توں, پھرٹز, ربکا, ہودنی, کوموڈو اتے Stockfish (کھلّہے سروت) ورگے پروگراماں نے منکھّاں نوں بہت پچھّے چھڈّ دتّا ہے۔ 2017 وچّ, ڈیپمن٘ڈ دے الفازیرو نے آپݨے آپ نوں اکلّے نیماں توں سکھائا اتے اکّ ٹیسٹ میچ وچّ Stockfish نوں ہرائا; لیلا شترن٘ج زیرو پروجیکٹ دءآرا نؤرل-نیٹّورک وچار کیتا گءآ سی۔ 2020 توں, Stockfish نے اینّ. اینّ. یو. ای. نیٹّورک دی ورتوں کیتی ہے اتے ہݨ دنیءآ دے سبھ توں مزبوت ان٘جݨاں وچّوں اکّ ہے; اہ سائیٹ سدھّے براؤزر وچّ Stockfish 19 چلاؤن٘دی ہے۔",
