  "e0w9qw": "اوپن گیم (1.e4 e5)۔ مووزہ 1.e4 e5 2.Nf3 Nc6 3.d4۔ وھائیٹ d4 نال اکّ وار وچّ کین٘در وچّ ٹٹّ جان٘دا ہے اتے کھیڈ نوں جلدی کھولھدا ہے۔ اس پہلکدمی نوں کائم رکھّدے ہوئے روئے لوپیز نالوں گھٹّ تھؤری۔",
  "1bnj3nj": "اوپن گیم (1.e4 e5)۔ مووزہ 1.e4 e5 2.Nf3 Nc6 3.Nc3 Nf6۔ سارے چار نائیٹس آپݨے سبھ توں کدرتی ورگ وچّ جان٘دے ہن۔ اکّ سن٘تلت, اسان-توں-ان٘ڈرسٹین٘ڈ گیم, سکھّݨ دے وکاس سدھان٘تاں لئی آدرش ہے۔",
  "1qmyr4l": "اوپن گیم (1.e4 e5)۔ مووزہ 1.e4 e5 2.Nf3 Nf6۔ بلیک e5 نوں نزرءان٘داز کردا ہے اتے e4 جوابی ہملءآں نوں سدھّا نزرءان٘داز کردا ہے۔ بہت مزبوت اتے اکسر سمانتا ولّ لے جان٘دا ہے۔ ساودھانہ 3.Nxe5 Nxe4?? 4.Qe2 نائیٹ جتّدا ہے۔",
