  "ss1lrm": "اوپن گیم (1.e4 e5)۔ مووزہ 1.e4 e5 2.Ke2۔ چٹّا راجا e2 تکّ جان٘دا ہے, جس نال کاسٹلن٘گ ہو جان٘دی ہے اتے آپݨی راݨی اتے بشپ نوں روکدی ہے۔ اکّ پرسدھّ ان٘ٹرنیٹّ مزاک اوپنن٘گ (کارلسن اتے ناکامرا نے اس نوں اکّ اسل ایوین٘ٹ وچّ وی کھیڈءآ)۔ اس دی نکل نا کرو!",
