  "vaiik2": "بھارتی رکھّءآ (1.d4, بلیک d5) توں بچءآ ہے۔ مووزہ 1.d4 f5 2.c4 Nf6 3.g3 e6 4.Bg2 d5۔ کالا d5,e6 اتے f5 اتّے اکّ موہرے دی کن٘دھ بݨاؤن٘دا ہے, جس نے نائیٹ لئی e4 نوں سٹّءآ۔ کیمت اکّ کمزور e5 ورگ اتے اکّ وءاست-ان لائیٹ-سءآئسڈ بشپ ہیہ دوواں پاسءآں لئی سپشّٹ یوجناواں۔",
  "svzmlw": "پھلین٘ک اوپنن٘گ۔ مووزہ 1.c4۔ چٹّے پاسے توں d5 نوں نین٘ترت کردا ہے, اکّ لچکدار سیٹّءاپّ رکھّدا ہے اتے اکسر g2 اتّے پھءآن٘چیٹوس رکھّدا ہے۔ کئی 1.d4 پرݨالیءآں وچّ ٹران٘سپوز ہو سکدا ہے۔",
  "1wxcf1h": "پھلین٘ک اوپنن٘گ۔ مووزہ 1.c4 e5 2.Nc3 Nf6۔ رن٘گاں دے نال اکّ سسلیءان الٹ اتے چٹّے لئی اکّ وادھو ٹین٘پو۔ چٹّا آم تور اتّے g3 اتے Bg2 کھیڈدا ہے, لن٘بے ترچھے دے نال دباؤن٘دا ہے۔",
  "18mehew": "پھلین٘ک اوپنن٘گ۔ مووزہ 1.Nf3 d5 2.c4۔ وھائیٹ کین٘در اتّے موہرے نال کبزا نہیں کردا پر نائیٹ, سی-پان اتے اکّ من٘گیتر بشپ دے نال اس اتّے ہملا کردا ہے۔ کلاسک ہائیپرموڈرن سوچ۔",
  "1jribvy": "پھلین٘ک اوپنن٘گ۔ مووزہ 1.Nf3 d5 2.g3 Nf6 3.Bg2 e6 4.O-O Be7 5.d3۔ وھائیٹ لئی اکّ پرݨالیہ Nf3, Bg2, کلھا, d3 پھر e4, جس توں باءاد اکّ کن٘گسائیڈ ہملا ہوئا۔ پھشر نے اس دی ورتوں سالاں تکّ کیتی۔",
  "18dmkge": "پھلین٘ک اوپنن٘گ۔ مووزہ 1.f4 d5 2.Nf3۔ وھائیٹ e5 نوں ایپھّ-پان نال نین٘ترت کردا ہے, جویں ک اکّ وادھو ٹین٘پو دے نال ڈچّ ڈپھین٘س۔ پھروم دے گین٘بی 1...e5 لئی دیکھو۔",
  "ly7u5t": "پھلین٘ک اوپنن٘گ۔ مووزہ 1.b3 e5 2.Bb2۔ b2 بشپ ترن٘ت e5 اتے کین٘در اتّے دباءا پاؤن٘دا ہے۔ اکّ درلبھّ اوپن-بیٹن-پاٹھن ستھتیءآں ولّ لے جان٘دا ہے۔",
  "1sutae7": "پھلین٘ک اوپنن٘گ۔ مووزہ 1.b4۔ وھائیٹ b2 نوں راݨی دے کنارے دی جگہا اتے من٘گیتر نوں پراپت کرن لئی بی-پان نوں دھکّ دن٘دا ہے۔ انسوچی, پر بلیک نوں ویکھݨا چاہیدا ہے کؤن٘ک b4 موہرے اگّ لگّ سکدی ہے۔",
  "1m764xa": "پھلین٘ک اوپنن٘گ۔ مووزہ 1.c4 c5۔ کالے شیشے c4 نوں...c5 نال۔ دوویں پکھّ اکسر من٘گیتر ہن٘دے ہن اتے کین٘در لئی اپ-سرلیکھ لڈدے ہن; اچّ پدھّر 'تے اکّ پسن٘دیدا رݨنیتک لڈائی دا میدان۔",
